"""Longest Palindromic Subsequence — LCS of the string with its reverse.

Equivalently an interval DP; the reverse trick reuses the LCS recurrence.

Time: O(n^2)   Space: O(n)
"""


class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        reverse = s[::-1]
        previous = [0] * (len(s) + 1)
        for a in s:
            current = [0]
            for j, b in enumerate(reverse):
                if a == b:
                    current.append(previous[j] + 1)
                else:
                    current.append(max(previous[j + 1], current[j]))
            previous = current
        return previous[-1]
